 const btn=(label:string,type:string,data:any={},cls='primary',disabled=false)=><button className={cls} disabled={busy||diceSettling||!!traveling||!human||paused||disabled||rolling} onClick={()=>act(type,data)}><NusaText text={label}/><ArrowRight size={17}/></button>;
