 {s.phase==='auction'&&<AuctionControls s={s} myId={myId} room={room} busy={busy||rolling||diceSettling||!!traveling||!!room&&!connected} bid={bid} setBid={setBid} act={act} setSeat={setLocalSeat}/>}
