 {s.phase==='debt'&&<><div className="debt-card"><small>KEWAJIBAN PEMBAYARAN</small><strong><NusaText text={money(s.debt.amount)}/></strong><p><NusaText text={nusaText(s.debt.label)}/> · penerima: {s.debt.to===null?'Bank':s.players[s.debt.to].name}</p><p>Saldo <NusaText text={money(who.cash)}/></p><span>Kekurangan <b><NusaText text={money(Math.max(0,s.debt.amount-who.cash))}/></b></span></div>{btn('Lunasi pembayaran','PAY',{},'primary',who.cash<s.debt.amount)}<button className="secondary" disabled={!human||busy} onClick={()=>{setLocalSeat(actor);setAssetPlayer(actor);setTab('aset');deferDecision()}}>Jual bangunan / gadaikan<Wallet size={18}/></button><button className="secondary" disabled={!human||busy} onClick={()=>{setLocalSeat(actor);setTab('barter');deferDecision()}}>Barter untuk mencari dana<Handshake size={18}/></button><button className="danger-text" disabled={!human||busy||bankruptcyShortfall(s,actor)<=0} onClick={()=>setSheet('bankrupt')}>Nyatakan bangkrut</button>{bankruptcyShortfall(s,actor)<=0&&<p className="fine">Nilai likuidasi aset masih cukup. Jual bangunan atau gadaikan dahulu.</p>}</>}
